CREATE TABLE v203492 (v203493 CHAR(15) CHARACTER SET utf8mb3 DEFAULT 'п©я┐я│я┌п╬') AS SELECT ST_SRID(ST_MULTILINESTRINGFROMWKB(@f, -1)), ST_SRID(ST_MLINEFROMWKB(@wkb_mls, 4294967296)), CRC32(CONCAT('good', 'year')), CURRENT_TIME(1), CURRENT_TIMESTAMP(6), EXTRACTVALUE('<a>a</a>', '/a[@x=@y0123456789_0123456789_0123456789_0123456789]'), CRC32(2 <= 4), ADDTIME(CAST(x2 AS DATETIME(0)), 100000.1)